export const file = {
  contents: [
    'export function greet(name: string = "world") {',
    `  const greeting = \`Welcome, \${name}!\`;`,
    "  return greeting;",
    "}",
    "",
  ].join("\n"),
  name: "greeting.ts",
};

import { useState } from "react";
import { FileView } from "@/registry/erbium/blocks/file-view";
import { Button } from "@/registry/erbium/ui/button";
import { file } from "../examples/file";

export default function FileViewStatesExample() {
  const [empty, setEmpty] = useState(false);

  return (
    <div className="grid w-full gap-4">
      <Button
        variant="outline"
        size="sm"
        onClick={() => {
          setEmpty(!empty);
        }}
      >
        Toggle empty source
      </Button>
      <FileView file={{ ...file, contents: empty ? "" : file.contents }} />
      <FileView
        file={{ contents: "Plaintext remains readable and copyable.", name: "notes.txt" }}
      />
    </div>
  );
}
